const s = P.stress;
let label, dir, col;
if (s <= -1.5){ label="Add reactant (N2/H2)"; dir=1; }
else if (s <= -0.5){ label="Increase pressure (compress)"; dir=1; }
else if (s < 0.5){ label="No stress (at equilibrium)"; dir=0; }
else if (s < 1.5){ label="Add product (NH3)"; dir=-1; }
else { label="Increase temperature"; dir=-1; }
col = dir>0 ? H.colors.accent2 : dir<0 ? H.colors.warn : H.colors.good;
const flow = (0.5 - 0.5*Math.cos(t*1.0));
const baseR = 50, baseP = 50;
const shift = dir * 18 * flow;
const rH = baseR - shift, pH = baseP + shift;
const bx=180, by=440, bw=120;
H.rect(bx, by-rH*2.6, bw, rH*2.6, {fill:H.colors.accent, radius:4});
